B.eB=new A.a7(58173,!1)
B.afq=new A.df("Tamamen iade edilen sipari\u015f bu d\xf6nemki paket say\u0131na dahil edilmez.",B.eB,B.av,B.ar,null)
B.V6=new A.a7(62329,!1)
B.afr=new A.df("Kural: Bir numaran\u0131n 2 sipari\u015fi teslim edilemezse o numara t\xfcm Doybi'de otomatik durur. M\xfc\u015fteri destekle konu\u015funca buradan a\xe7ars\u0131n.",B.V6,B.av,B.ar,null)
B.Uj=new A.a7(58151,!1)
B.afs=new A.df('\xd6deme bildirildi \xb7 Doybi kontrol ediyor. Para hesab\u0131m\u0131za ge\xe7ti\u011finde ekibimiz onaylar; o zaman "\xd6dendi" g\xf6r\xfcn\xfcr.',B.Uj,B.av,B.ar,null)
B.aft=new A.df("\u015eimdilik kuryesi olan restoranlarla \xe7al\u0131\u015f\u0131yoruz. Yine de ba\u015fvurabilirsin; kuryeni bulunca seni yay\u0131na al\u0131r\u0131z.",B.eB,B.av,B.ar,null)
B.UZ=new A.a7(61877,!1)
B.afu=new A.df("Talebin al\u0131nd\u0131. Doybi \xf6deme bilgisini iletir. \xd6demen onaylan\u0131nca 30 g\xfcnl\xfck d\xf6nemin ba\u015flar. Kart\u0131ndan otomatik \xf6deme al\u0131nmaz.",B.UZ,B.aB,B.a0,null)
B.afv=new A.df("Bir \xfcr\xfcn bittiyse kapat; m\xfc\u015fteri onu sipari\u015f edemez, ertesi g\xfcn tekrar a\xe7.",B.eB,B.av,B.ar,null)
B.UG=new A.a7(59084,!1)
B.afw=new A.df("Son \xf6deme tarihi ge\xe7ti. \xd6demeyi yapt\u0131ysan bildir.",B.UG,B.aN,B.M,null)
B.afx=new A.df("Bu ay\u0131n kontenjan\u0131 doldu. Gelecek ay yeniden a\xe7\u0131l\u0131nca talep g\xf6nderebilirsin.",B.eB,B.av,B.ar,null)
B.Ul=new A.a7(58289,!1)
B.afy=new A.df("Otomatik \xfccretli yenileme kapal\u0131; restoran\u0131n a\xe7\u0131k onay\u0131 olmadan yenilenmez.",B.Ul,B.av,B.ar,null)
B.afz=new A.df("Restoran kapal\u0131 g\xf6r\xfcn\xfcyor; m\xfc\u015fteriler sipari\u015f veremez. A\xe7mak i\xe7in \xfcstteki d\xfc\u011fmeye bas.",B.id,B.aN,B.M,null)
B.UL=new A.a7(61112,!1)
B.afA=new A.df("\xd6\u011frenci kimli\u011fini yan\u0131na al. Teslimde ge\xe7erli \xf6\u011frenci kimli\u011fini g\xf6stermen gerekiyor. Kimli\u011fini uygulamaya y\xfcklemiyorsun; restoran sadece bakar, foto\u011fraf\u0131n\u0131 \xe7ekmez, kaydetmez.",B.UL,B.av,B.ar,null)
B.afB=new A.df("\xd6deme kap\u0131da oldu\u011fu i\xe7in senden para al\u0131nmad\u0131. Restorana ve Doybi ekibine hemen iletiyoruz.",B.eB,B.av,B.ar,null)
B.afC=new A.df("D\xfckk\xe2n fiyat\u0131 kural\u0131: Doybi'deki fiyatlar\u0131n d\xfckk\xe2ndaki fiyat\u0131nla ayn\u0131 olmal\u0131. Komisyon olmad\u0131\u011f\u0131 i\xe7in fiyat \u015fi\u015firmeye gerek yok; m\xfc\u015fteriye de bunu s\xf6yl\xfcyoruz.",B.uZ,B.av,B.ar,null)
B.afD=new A.df("Doybi sana \u20ba50 indirim kuponu tan\u0131mlad\u0131. Kuponlar\u0131m'da g\xf6rebilirsin.",B.ie,B.aB,B.a0,null)
B.afE=new A.df("\u0130kram\u0131n maliyetini sen kar\u015f\u0131lars\u0131n. \xd6\u011frenciden \xfccret al\u0131nmaz; Doybi komisyon ya da \xf6deme almaz ve ikramlar abonelik sipari\u015f say\u0131na eklenmez.",B.eB,B.av,B.ar,null)
B.afF=new A.df("Bu restorana \u015fu an sipari\u015f veremiyorsun. Bir yanl\u0131\u015fl\u0131k oldu\u011funu d\xfc\u015f\xfcn\xfcyorsan Yard\u0131m'dan bize yaz.",B.ol,B.aN,B.M,null)
B.afG=new A.df("Ba\u015fvurun Doybi ekibine iletildi. Genelde 1 i\u015f g\xfcn\xfc i\xe7inde seni aray\u0131p kurulumu birlikte yap\u0131yoruz.",B.eB,B.av,B.ar,null)
B.afH=new A.df("\u0130lk 3 ay \xfccretsiz: ilk \xfc\xe7 d\xf6nem (30'ar g\xfcn) \xfccret al\u0131nmaz; ilk d\xf6nem giri\u015f paketiyle ba\u015flar. 4. d\xf6nemden itibaren paketin, bir \xf6nceki d\xf6nemde teslim etti\u011fin sipari\u015fe g\xf6re belirlenir. Yemek paras\u0131 kap\u0131da do\u011frudan sana \xf6denir; Doybi sipari\u015ften pay almaz.",B.uO,B.aB,B.a0,null)
